export const GLOSSARY_SHARD = Object.freeze({"ethereum":{"slug":"ethereum","cat":"basics","en":"Ethereum (ETH)","contentLocale":"vi","term":"Ethereum (ETH)","aka":["ETH","Ether"],"short":"Ethereum là blockchain cho phép chạy hợp đồng thông minh và ứng dụng phi tập trung, còn ETH (Ether) là đồng coin gốc dùng để trả phí gas và staking trên mạng này.","body":[["Nếu ",["Bitcoin","bitcoin"]," chủ yếu là mạng chuyển giá trị, thì Ethereum giống một máy tính toàn cầu: ai cũng có thể triển khai chương trình (",["hợp đồng thông minh","smart-contract"],") lên đó. Nhờ vậy mới có ",["DeFi","defi"],", ",["NFT","nft"],", ",["stablecoin","stablecoin"]," dạng token ERC-20 và hàng nghìn ứng dụng khác."],["Mỗi thao tác trên Ethereum đều tốn ",["phí gas","gas-fee"]," trả bằng ETH. Từ tháng 9 năm 2022 (sự kiện The Merge), Ethereum chuyển từ đào coin sang bằng chứng cổ phần: validator khóa ETH để xác thực khối thay cho thợ đào."],"Khi mạng chính đông, phí gas có thể cao, nên nhiều người dùng các mạng layer 2 như Arbitrum, Optimism hay Base để giao dịch rẻ hơn. Trên sàn, bạn sẽ thấy cùng một token có thể rút qua mạng Ethereum (ERC20) hoặc qua layer 2, với phí và thời gian khác nhau."],"example":"Giả sử bạn muốn đổi 300 USDC sang một token khác trên một sàn DEX. Trên mạng chính Ethereum, lúc mạng bận, phí gas cho lần swap có thể khoảng 0,003 ETH; với ETH ở giá 2.000 USDT, đó là 6 USDT, tức 2% số tiền bạn đổi. Nếu làm cùng thao tác trên một layer 2 với phí khoảng 0,0001 ETH, bạn chỉ tốn 0,2 USDT. Con số thực tế thay đổi liên tục theo độ bận của mạng.","mistakes":["Chỉ giữ token mà không giữ chút ETH nào trong ví, nên không có ETH để trả phí gas khi muốn chuyển.","Rút token từ sàn qua mạng layer 2 nhưng ví nhận lại đang mở ở mạng chính Ethereum và nghĩ là mất tiền.","Nhầm Ethereum (ETH) với Ethereum Classic (ETC), hai mạng khác nhau."],"faq":[{"q":"Ethereum khác Bitcoin như thế nào?","a":"Bitcoin tập trung vào chuyển và lưu giữ giá trị, còn Ethereum là nền tảng chạy hợp đồng thông minh. Ethereum dùng bằng chứng cổ phần từ năm 2022, trong khi Bitcoin vẫn dùng bằng chứng công việc."},{"q":"ETH có giới hạn nguồn cung không?","a":"ETH không có mức trần cố định như 21 triệu BTC. Nguồn cung thay đổi theo lượng ETH phát hành cho validator và lượng phí bị đốt theo cơ chế EIP-1559."}],"title":"Ethereum (ETH) là gì? Giải thích dễ hiểu","description":"Ethereum là gì, ETH dùng để làm gì, phí gas và staking hoạt động ra sao, và vì sao nhiều người dùng layer 2.","related":[["smart-contract","Hợp đồng thông minh (Smart contract)","Hợp đồng thông minh (smart contract) là chương trình được triển khai trên blockchain, tự động thực hiện các điều kiện đã lập trình khi có giao dịch gọi tới mà không cần bên trung gian."],["gas-fee","Phí gas (Gas fee)","Phí gas là khoản phí bạn trả cho mạng blockchain để xử lý một giao dịch hoặc thao tác với hợp đồng thông minh, tính bằng coin gốc của mạng như ETH trên Ethereum."],["proof-of-stake","Bằng chứng cổ phần (Proof of Stake - PoS)","Bằng chứng cổ phần (Proof of Stake, PoS) là cơ chế đồng thuận trong đó validator khóa coin của mạng làm tài sản đảm bảo để được quyền đề xuất và xác thực khối mới, thay cho việc đào bằng máy."],["layer-2","Layer 2 (L2, giải pháp lớp 2)","Layer 2 (L2) là mạng xây trên một blockchain lớp 1, xử lý giao dịch bên ngoài chuỗi chính rồi gửi kết quả gom lại về L1, giúp giao dịch nhanh hơn và phí rẻ hơn."],["defi","DeFi (Tài chính phi tập trung)","DeFi (tài chính phi tập trung) là các dịch vụ tài chính như giao dịch, cho vay, gửi tiết kiệm chạy bằng hợp đồng thông minh trên blockchain, không cần ngân hàng hay sàn tập trung làm trung gian."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":true},"layer-1":{"slug":"layer-1","cat":"basics","en":"Layer 1 (L1)","contentLocale":"vi","term":"Layer 1 (L1, blockchain lớp 1)","aka":["L1","blockchain lớp 1","chuỗi lớp 1"],"short":"Layer 1 (L1) là blockchain nền tảng tự xử lý và xác nhận giao dịch bằng cơ chế đồng thuận riêng, có coin gốc riêng, như Bitcoin, Ethereum, Solana hay BNB Chain.","body":[["Một blockchain lớp 1 tự lo mọi thứ: lưu dữ liệu, chạy cơ chế đồng thuận (",["PoW","proof-of-work"]," hoặc ",["PoS","proof-of-stake"],") và đảm bảo giao dịch là cuối cùng. Coin gốc như ",["BTC","bitcoin"],", ",["ETH","ethereum"],", SOL dùng để trả phí và bảo vệ mạng."],["Các L1 phải cân bằng giữa ba yếu tố: phi tập trung, bảo mật và khả năng mở rộng. Có mạng ưu tiên tốc độ và phí rẻ, có mạng ưu tiên số lượng ",["node","node"]," lớn và độ bền. Vì vậy mới có các giải pháp ",["layer 2","layer-2"]," xây trên L1 để xử lý thêm giao dịch."],"Khi bạn rút tiền trên sàn, danh sách mạng (Bitcoin, ERC20, TRC20, BEP20, Solana) thực chất là các blockchain khác nhau. Gửi qua mạng mà ví nhận không hỗ trợ có thể làm mất tiền hoặc phải chờ hỗ trợ xử lý rất lâu."],"example":"Giả sử bạn muốn chuyển 500 USDT sang ví khác. Nếu chọn mạng Ethereum lúc mạng bận, phí có thể khoảng 3 USDT, người nhận nhận 497 USDT. Nếu chọn một L1 khác như Tron hoặc Solana mà ví người nhận hỗ trợ, phí có thể chỉ dưới 1 USDT. Phí rút thực tế do sàn đặt ra và thay đổi theo thời điểm, nên hãy xem trên trang rút trước khi xác nhận.","mistakes":["Chọn mạng rút rẻ nhất mà không kiểm tra ví nhận có hỗ trợ mạng đó hay không.","Nghĩ rằng L1 nhanh và rẻ hơn thì tốt hơn về mọi mặt, bỏ qua mức độ phi tập trung.","Nhầm token chạy trên một L1 với coin gốc của L1 đó."],"faq":[{"q":"Layer 1 khác layer 2 thế nào?","a":"Layer 1 là blockchain gốc tự xác nhận giao dịch. Layer 2 xây trên L1, xử lý giao dịch bên ngoài rồi gửi kết quả về L1 để tận dụng bảo mật của nó."},{"q":"Những blockchain nào là Layer 1?","a":"Ví dụ phổ biến là Bitcoin, Ethereum, Solana, BNB Chain, Avalanche, Cardano và Tron. Mỗi mạng có cơ chế đồng thuận và coin gốc riêng."}],"title":"Layer 1 (L1) là gì? Blockchain lớp 1","description":"Layer 1 là gì, ví dụ các blockchain L1 phổ biến, khác layer 2 ra sao và vì sao chọn đúng mạng khi rút coin.","related":[["layer-2","Layer 2 (L2, giải pháp lớp 2)","Layer 2 (L2) là mạng xây trên một blockchain lớp 1, xử lý giao dịch bên ngoài chuỗi chính rồi gửi kết quả gom lại về L1, giúp giao dịch nhanh hơn và phí rẻ hơn."],["blockchain","Blockchain (chuỗi khối)","Blockchain (chuỗi khối) là một sổ cái số được chia sẻ, trong đó các giao dịch được gom thành từng khối và nối với nhau theo thứ tự, nên muốn sửa dữ liệu cũ thì phải làm lại toàn bộ các khối phía sau."],["ethereum","Ethereum (ETH)","Ethereum là blockchain cho phép chạy hợp đồng thông minh và ứng dụng phi tập trung, còn ETH (Ether) là đồng coin gốc dùng để trả phí gas và staking trên mạng này."],["gas-fee","Phí gas (Gas fee)","Phí gas là khoản phí bạn trả cho mạng blockchain để xử lý một giao dịch hoặc thao tác với hợp đồng thông minh, tính bằng coin gốc của mạng như ETH trên Ethereum."],["coin-vs-token","Coin và token (Coin vs token)","Coin là tài sản gốc của một blockchain riêng như BTC hay ETH, còn token là tài sản được tạo trên một blockchain có sẵn thông qua hợp đồng thông minh, như USDT trên Ethereum hay Tron."]],"lesson":null,"coin":{"slug":"solana","name":"Solana","symbol":"SOL"},"tool":null,"cta":false},"token-burn":{"slug":"token-burn","cat":"basics","en":"Token burn","contentLocale":"vi","term":"Đốt token (Token burn)","aka":["token burn","đốt coin","burn"],"short":"Đốt token (token burn) là việc gửi token tới một địa chỉ không ai có thể truy cập hoặc hủy chúng bằng hợp đồng, khiến lượng token đó bị loại vĩnh viễn khỏi nguồn cung.","body":[["Có nhiều cách đốt: dự án dùng một phần doanh thu mua lại token rồi đốt, giao thức tự động đốt một phần phí, hoặc đốt token chưa phân phối. Ví dụ BNB có cơ chế đốt định kỳ, còn ",["Ethereum","ethereum"]," đốt phần phí cơ bản theo EIP-1559."],["Đốt làm giảm tổng cung, nhưng ảnh hưởng tới giá phụ thuộc vào quy mô. Đốt 0,1% nguồn cung mỗi quý gần như không đáng kể nếu cùng lúc dự án phát hành thêm 5% mỗi năm cho ",["staking","staking"]," hoặc ",["mở khóa token","token-unlock"],". Hãy nhìn nguồn cung ròng: phát hành mới trừ lượng đốt."],["Việc đốt có thể kiểm chứng trên ",["trình khám phá khối","block-explorer"]," bằng cách xem giao dịch gửi tới địa chỉ đốt. Đừng chỉ dựa vào thông báo của dự án; hãy kiểm tra xem lượng đốt là từ token thật đang lưu hành hay từ phần dự trữ chưa từng ra thị trường."]],"example":["Một token có tổng cung 500 triệu. Mỗi quý dự án dùng 20% phí thu được để mua lại và đốt; quý này đốt được 2 triệu token, tức 0,4% tổng cung. Nhưng cùng quý đó có 10 triệu token được mở khóa cho đội ngũ. ",["Nguồn cung lưu hành","circulating-supply"]," ròng vẫn tăng 8 triệu token. Nếu không có đợt mở khóa, sau 4 quý đốt như vậy tổng cung sẽ giảm còn 492 triệu."],"mistakes":["Thấy thông báo đốt token rồi cho rằng giá chắc chắn sẽ tăng.","Không so sánh lượng đốt với lượng phát hành mới và mở khóa.","Tin vào con số đốt mà không kiểm chứng trên chuỗi."],"faq":[{"q":"Token bị đốt có lấy lại được không?","a":"Không. Token gửi tới địa chỉ đốt không có khóa riêng tư nào kiểm soát, nên bị loại khỏi nguồn cung vĩnh viễn."},{"q":"Vì sao dự án đốt token?","a":"Để giảm nguồn cung, chia lại giá trị cho người nắm giữ hoặc loại bỏ token chưa dùng đến. Hiệu quả thực tế tùy vào tổng thể tokenomics."}],"title":"Đốt token là gì? Token burn ảnh hưởng ra sao","description":"Token burn là gì, các cách đốt token, vì sao đốt không chắc làm giá tăng và cách kiểm chứng lượng đốt trên chuỗi.","related":[["tokenomics","Tokenomics (kinh tế học token)","Tokenomics là toàn bộ thiết kế kinh tế của một token: tổng cung, cách phân bổ, lịch mở khóa, cơ chế phát hành và đốt, cùng công dụng khiến người dùng cần giữ hoặc dùng token đó."],["circulating-supply","Nguồn cung lưu hành (Circulating supply)","Nguồn cung lưu hành (circulating supply) là số lượng coin hoặc token đang thực sự có trên thị trường và có thể giao dịch, không tính phần bị khóa, chưa phát hành hoặc đã bị đốt."],["market-capitalization","Vốn hóa thị trường (Market cap)","Vốn hóa thị trường (market cap) của một đồng tiền mã hóa là giá hiện tại nhân với nguồn cung lưu hành, cho biết tổng giá trị thị trường đang định cho lượng coin đang lưu thông."],["coin-vs-token","Coin và token (Coin vs token)","Coin là tài sản gốc của một blockchain riêng như BTC hay ETH, còn token là tài sản được tạo trên một blockchain có sẵn thông qua hợp đồng thông minh, như USDT trên Ethereum hay Tron."]],"lesson":null,"coin":{"slug":"bnb","name":"BNB","symbol":"BNB"},"tool":null,"cta":false},"fud":{"slug":"fud","cat":"basics","en":"FUD","contentLocale":"vi","term":"FUD (sợ hãi, bất an, nghi ngờ)","aka":["FUD","fear uncertainty doubt","tin FUD"],"short":"FUD (Fear, Uncertainty, Doubt) là thông tin hoặc tâm lý gây sợ hãi, bất an và nghi ngờ về một dự án hay thị trường, có thể đúng sự thật hoặc bị phóng đại để làm giá giảm.","body":["FUD có thể đến từ tin tức pháp lý, lỗi bảo mật, tin đồn sàn gặp khó khăn hay một bài đăng của người có ảnh hưởng. Khi FUD lan rộng, nhiều người bán vội, giá giảm nhanh, và tin đồn càng được tin hơn.","Điều quan trọng là FUD không đồng nghĩa với tin giả. Một số cảnh báo hoàn toàn đúng và cứu được nhiều người. Ngược lại, cộng đồng của một dự án đôi khi gọi mọi phê bình là FUD để né câu hỏi khó. Đừng gạt bỏ cũng đừng tin ngay.",["Cách xử lý: xác minh nguồn gốc tin, kiểm tra thông báo chính thức, dữ liệu trên chuỗi (ví dụ dòng tiền ra khỏi sàn, ví lớn chuyển coin) và ",["bằng chứng dự trữ","proof-of-reserves"]," của sàn. Quyết định dựa trên dữ kiện, không dựa trên mức độ ồn ào."]],"example":["Giả sử có tin đồn một sàn tạm dừng rút tiền và token của sàn giảm 25% trong 2 giờ, từ 8 ",["USDT","usdt"]," xuống 6 USDT. Bạn đang giữ 500 token, trị giá giảm từ 4.000 xuống 3.000 USDT. Thay vì bán ngay, bạn kiểm tra kênh chính thức và thấy sàn chỉ bảo trì một mạng rút trong 30 phút. Ngược lại, nếu dữ liệu trên chuỗi cho thấy ",["ví nóng","hot-wallet"]," của sàn đã cạn và nhiều người báo không rút được, đó là FUD có cơ sở và cần hành động thận trọng."],"mistakes":["Bán toàn bộ chỉ vì một bài đăng chưa xác minh trên mạng xã hội.","Gọi mọi cảnh báo là FUD và bỏ qua dấu hiệu rủi ro thật.","Tin vào ảnh chụp màn hình thay vì nguồn tin gốc và dữ liệu trên chuỗi."],"faq":[{"q":"FUD có phải luôn là tin giả không?","a":"Không. FUD chỉ mô tả thông tin gây sợ hãi; nó có thể đúng, sai hoặc bị phóng đại. Việc của bạn là xác minh trước khi phản ứng."},{"q":"FUD khác FOMO thế nào?","a":"FOMO là sợ bỏ lỡ, khiến bạn mua vội khi giá tăng. FUD là sợ hãi và nghi ngờ, khiến bạn bán vội khi có tin xấu."}],"title":"FUD là gì? Ý nghĩa FUD trong crypto","description":"FUD là gì, vì sao tin gây sợ hãi làm giá giảm nhanh và cách phân biệt cảnh báo có cơ sở với tin đồn phóng đại.","related":[["fomo","FOMO (sợ bỏ lỡ)","FOMO (fear of missing out) là nỗi sợ bỏ lỡ cơ hội, khiến người giao dịch vội mua một tài sản đang tăng nóng mà không có kế hoạch, thường ở mức giá đã cao."],["bear-market","Thị trường giảm giá (Bear market)","Thị trường giảm giá (bear market) là giai đoạn giá giảm kéo dài, thường hơn 20% từ đỉnh, kèm tâm lý bi quan, khối lượng giao dịch thấp và dòng tiền rút khỏi thị trường."],["fear-and-greed-index","Chỉ số Sợ hãi và Tham lam (Fear and Greed Index)","Chỉ số Sợ hãi và Tham lam là thang điểm từ 0 đến 100 tóm tắt tâm lý thị trường crypto, trong đó điểm thấp thể hiện sợ hãi và điểm cao thể hiện tham lam."],["on-chain-analysis","Phân tích on-chain","Phân tích on-chain là việc đọc dữ liệu công khai trên blockchain như giao dịch, số dư ví và dòng tiền ra vào sàn để hiểu hành vi của người tham gia thị trường."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Có người bảo giúp bạn kiếm tiền. Hãy xem họ đòi hỏi điều gì trước đã."},"coin":null,"tool":null,"cta":false},"bid-ask-spread":{"slug":"bid-ask-spread","cat":"trading","en":"Bid-ask spread","contentLocale":"vi","term":"Chênh lệch giá mua-bán (Spread)","aka":["spread","bid-ask spread","chênh lệch giá"],"short":"Chênh lệch giá mua-bán (bid-ask spread) là khoảng cách giữa giá mua cao nhất (bid) và giá bán thấp nhất (ask) trong sổ lệnh, và là chi phí ngầm mỗi khi bạn mua rồi bán ngay bằng lệnh thị trường.","body":[["Giá bạn thấy trên biểu đồ thường là ",["giá khớp gần nhất","last-price"],", nhưng khi mua bằng ",["lệnh thị trường","market-order"]," bạn trả giá ask, còn khi bán bạn nhận giá bid. Spread càng rộng thì bạn càng mất nhiều ngay khi vào lệnh."],["Cặp có ",["thanh khoản","liquidity"]," cao như ",["BTC","bitcoin"],"/",["USDT","usdt"]," trên sàn lớn thường có spread rất hẹp, chỉ một bước giá. Coin nhỏ, cặp ít người giao dịch hoặc thời điểm tin tức mạnh có thể có spread rộng hơn nhiều. Các ",["nhà tạo lập thị trường (market maker)","market-maker"]," kiếm lời một phần nhờ spread và giúp thu hẹp nó."],"Spread khác phí giao dịch: phí do sàn thu và được công bố, còn spread nằm trong giá. Với ứng dụng mua nhanh hoặc P2P, chênh lệch thường được gộp vào tỷ giá hiển thị. So sánh tổng chi phí, gồm cả phí và spread, mới cho bạn bức tranh đúng."],"example":"Giả sử một altcoin có giá bid 0,995 USDT và ask 1,005 USDT, spread là 0,01 USDT, tức khoảng 1% so với giá giữa 1,000. Bạn mua 2.000 USDT bằng lệnh thị trường ở 1,005, nhận khoảng 1.990 token. Nếu bán ngay ở 0,995, bạn nhận khoảng 1.980 USDT, mất 20 USDT chỉ vì spread, chưa tính phí. Với BTC/USDT có spread 0,01%, cùng thao tác chỉ mất khoảng 0,2 USDT.","mistakes":["Chỉ so sánh phí giao dịch mà bỏ qua spread khi chọn sàn hoặc cặp.","Dùng lệnh thị trường với coin có spread rộng thay vì đặt lệnh giới hạn.","Giao dịch ngay lúc có tin lớn khi spread bị nới rộng đột ngột."],"faq":[{"q":"Spread rộng có nghĩa là gì?","a":"Spread rộng thường cho thấy thanh khoản thấp hoặc thị trường đang biến động mạnh. Bạn sẽ chịu chi phí ngầm cao hơn khi dùng lệnh thị trường."},{"q":"Làm sao tránh mất tiền vì spread?","a":"Đặt lệnh giới hạn ở giá mong muốn, chọn cặp có thanh khoản cao và tránh giao dịch lúc thị trường hỗn loạn."}],"title":"Spread là gì? Chênh lệch giá mua-bán","description":"Bid-ask spread là gì, vì sao nó là chi phí ngầm khi giao dịch và cách giảm thiệt hại do spread rộng.","related":[["order-book","Sổ lệnh (Order book)","Sổ lệnh (order book) là danh sách theo thời gian thực của tất cả lệnh mua và lệnh bán đang chờ khớp cho một cặp giao dịch, sắp xếp theo mức giá và khối lượng."],["slippage","Trượt giá (Slippage)","Trượt giá (slippage) là phần chênh lệch giữa giá bạn dự kiến khi đặt lệnh và giá khớp thực tế, xảy ra khi thanh khoản không đủ hoặc giá thay đổi trong lúc lệnh đang được xử lý."],["liquidity","Thanh khoản (Liquidity)","Thanh khoản là mức độ dễ dàng mua hoặc bán một tài sản với số lượng lớn mà giá không bị đẩy đi nhiều."],["market-maker","Nhà tạo lập thị trường (Market maker)","Nhà tạo lập thị trường (market maker) là cá nhân hoặc tổ chức liên tục đặt lệnh mua và lệnh bán cho một tài sản để cung cấp thanh khoản và kiếm lời từ chênh lệch giá."],["maker-taker-fees","Phí maker và phí taker (Maker/Taker fee)","Phí maker và phí taker là hai mức phí giao dịch khác nhau: maker trả phí khi lệnh của bạn nằm chờ trên sổ lệnh và tạo thêm thanh khoản, taker trả phí khi lệnh của bạn khớp ngay với lệnh có sẵn."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"Tại sao giá trên màn hình không phải là giá khớp lệnh của tôi?"},"coin":null,"tool":"/rates","cta":false},"slippage":{"slug":"slippage","cat":"trading","en":"Slippage","contentLocale":"vi","term":"Trượt giá (Slippage)","aka":["slippage","trượt giá","độ trượt giá"],"short":"Trượt giá (slippage) là phần chênh lệch giữa giá bạn dự kiến khi đặt lệnh và giá khớp thực tế, xảy ra khi thanh khoản không đủ hoặc giá thay đổi trong lúc lệnh đang được xử lý.","body":[["Trên ",["sàn tập trung","centralized-exchange"],", trượt giá xảy ra khi ",["lệnh thị trường","market-order"]," lớn hơn khối lượng ở mức giá tốt nhất, nên phải ăn sâu vào các mức giá kém hơn trong ",["sổ lệnh","order-book"],". Trên ",["DEX","dex"]," dùng ",["pool thanh khoản","liquidity-pool"],", mỗi lần mua làm giá trong pool dịch chuyển, nên lệnh càng lớn so với pool thì trượt giá càng nhiều."],["Trên DEX, bạn đặt mức trượt giá cho phép, ví dụ 0,5%. Nếu giá khớp tệ hơn mức đó, giao dịch bị hủy (vẫn mất ",["phí gas","gas-fee"],"). Đặt quá cao giúp lệnh dễ khớp nhưng tạo cơ hội cho bot chèn lệnh trước và sau bạn (sandwich)."],"Trượt giá có thể có lợi, khi giá di chuyển theo hướng tốt cho bạn, nhưng thường người ta lo phần bất lợi. Lệnh giới hạn giúp bạn không bao giờ khớp ở giá tệ hơn mức đặt, đổi lại có thể không khớp."],"example":"Giả sử bạn mua một token trên DEX bằng 5.000 USDC, giá hiển thị 2 USDC, kỳ vọng nhận 2.500 token. Pool chỉ có thanh khoản khoảng 100.000 USDC, nên lệnh của bạn đẩy giá lên và giá khớp trung bình là 2,1 USDC. Bạn chỉ nhận khoảng 2.381 token, trượt giá khoảng 4,8%. Nếu bạn đặt mức trượt giá cho phép 1%, giao dịch sẽ bị từ chối thay vì khớp ở giá đó.","mistakes":["Đặt trượt giá cho phép 10% đến 20% trên DEX chỉ để lệnh chắc chắn khớp.","Đặt lệnh thị trường lớn với coin có sổ lệnh mỏng.","Nhầm trượt giá với phí giao dịch và không tính nó vào chi phí."],"faq":[{"q":"Nên đặt trượt giá bao nhiêu trên DEX?","a":"Với cặp thanh khoản cao, mức thấp như 0,1% đến 0,5% thường đủ. Token thanh khoản mỏng hoặc có thuế giao dịch có thể cần cao hơn, nhưng mức cao làm tăng rủi ro bị bot lợi dụng."},{"q":"Trượt giá khác spread thế nào?","a":"Spread là khoảng cách giữa giá mua và giá bán tốt nhất. Trượt giá là phần bạn mất thêm khi lệnh phải khớp sâu hơn hoặc giá thay đổi trong lúc xử lý."}],"title":"Slippage là gì? Trượt giá khi giao dịch crypto","description":"Trượt giá (slippage) là gì, vì sao lệnh lớn khớp ở giá kém hơn, cách đặt mức trượt giá trên DEX và tránh bot sandwich.","related":[["bid-ask-spread","Chênh lệch giá mua-bán (Spread)","Chênh lệch giá mua-bán (bid-ask spread) là khoảng cách giữa giá mua cao nhất (bid) và giá bán thấp nhất (ask) trong sổ lệnh, và là chi phí ngầm mỗi khi bạn mua rồi bán ngay bằng lệnh thị trường."],["market-order","Lệnh thị trường (Market order)","Lệnh thị trường (market order) là lệnh mua hoặc bán ngay lập tức ở giá tốt nhất hiện có trong sổ lệnh, ưu tiên tốc độ khớp thay vì kiểm soát giá."],["liquidity","Thanh khoản (Liquidity)","Thanh khoản là mức độ dễ dàng mua hoặc bán một tài sản với số lượng lớn mà giá không bị đẩy đi nhiều."],["order-book","Sổ lệnh (Order book)","Sổ lệnh (order book) là danh sách theo thời gian thực của tất cả lệnh mua và lệnh bán đang chờ khớp cho một cặp giao dịch, sắp xếp theo mức giá và khối lượng."],["amm","Tạo lập thị trường tự động (AMM)","AMM (tạo lập thị trường tự động) là cơ chế của nhiều DEX dùng công thức toán học và pool thanh khoản để định giá và khớp giao dịch, thay cho sổ lệnh mua bán truyền thống."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"Tại sao giá trên màn hình không phải là giá khớp lệnh của tôi?"},"coin":null,"tool":"/rates","cta":false},"trailing-stop":{"slug":"trailing-stop","cat":"trading","en":"Trailing stop","contentLocale":"vi","term":"Lệnh cắt lỗ động (Trailing stop)","aka":["trailing stop","dừng lỗ di động","cắt lỗ động"],"short":"Lệnh cắt lỗ động (trailing stop) là lệnh dừng có giá kích hoạt tự động di chuyển theo giá khi giá đi đúng hướng, giữ một khoảng cách cố định, và chỉ kích hoạt khi giá đảo chiều đủ khoảng cách đó.","body":["Bạn đặt khoảng cách theo phần trăm hoặc số tiền, gọi là callback hoặc độ lùi. Với vị thế mua, khi giá lên đỉnh mới, mức kích hoạt được nâng lên theo; khi giá giảm, mức kích hoạt đứng yên. Nếu giá giảm từ đỉnh đúng bằng khoảng cách đã đặt, lệnh đóng vị thế.","Trailing stop giúp bạn để lợi nhuận chạy theo xu hướng mà vẫn khóa được phần lớn lãi khi giá quay đầu. Một số sàn cho phép đặt giá kích hoạt ban đầu, tức trailing stop chỉ bắt đầu theo dõi khi giá đạt một mức nhất định.",["Chọn khoảng cách là phần khó: quá hẹp thì bị quét bởi dao động thông thường, quá rộng thì trả lại nhiều lợi nhuận. Hãy dựa vào mức ",["biến động","volatility"]," thường thấy của cặp đó. Khi kích hoạt, lệnh thường là ",["lệnh thị trường","market-order"]," nên vẫn có thể ",["trượt giá","slippage"],"."]],"example":["Bạn mua ",["ETH","ethereum"]," ở 2.000 ",["USDT","usdt"]," và đặt trailing stop với khoảng lùi 5%. Ban đầu mức kích hoạt là 1.900. Giá tăng lên 2.400, mức kích hoạt tự động lên 2.280. Giá tiếp tục lên 2.600, mức kích hoạt thành 2.470. Sau đó giá giảm về 2.470 và lệnh kích hoạt. Với 1 ETH, bạn chốt khoảng 470 USDT lãi, dù không ai biết trước đỉnh là 2.600."],"mistakes":["Đặt khoảng lùi 1% cho coin dao động 5% mỗi ngày và bị quét ra ngay.","Nghĩ rằng trailing stop đảm bảo khớp đúng giá kích hoạt.","Dùng trailing stop khi giá đang đi ngang, khiến lệnh bị kích hoạt liên tục mà không có xu hướng."],"faq":[{"q":"Trailing stop có đi xuống khi giá giảm không?","a":"Không. Với vị thế mua, mức kích hoạt chỉ đi lên theo đỉnh mới và đứng yên khi giá giảm. Với vị thế bán, nó di chuyển theo chiều ngược lại."},{"q":"Callback rate trong trailing stop là gì?","a":"Callback rate là khoảng cách phần trăm từ đỉnh (hoặc đáy với lệnh bán) mà giá phải lùi lại để kích hoạt lệnh."}],"title":"Trailing stop là gì? Lệnh cắt lỗ động","description":"Trailing stop là gì, mức kích hoạt di chuyển theo giá thế nào, cách chọn khoảng lùi và những lưu ý khi sử dụng.","related":[["stop-loss","Lệnh cắt lỗ (Stop-loss)","Lệnh cắt lỗ (stop-loss) là lệnh tự động đóng vị thế khi giá chạm một mức bạn đặt trước, nhằm giới hạn khoản lỗ trong trường hợp thị trường đi ngược kỳ vọng."],["take-profit","Lệnh chốt lời (Take-profit)","Lệnh chốt lời (take-profit) là lệnh tự động đóng toàn bộ hoặc một phần vị thế khi giá đạt mức lợi nhuận bạn đặt trước, giúp bạn khóa lãi mà không cần theo dõi màn hình liên tục."],["stop-limit-order","Lệnh dừng giới hạn (Stop-limit)","Lệnh dừng giới hạn (stop-limit) là lệnh có hai mức giá: khi giá chạm giá kích hoạt (stop), sàn đặt một lệnh giới hạn ở giá giới hạn (limit) bạn đã chọn, thay vì một lệnh thị trường."],["volatility","Biến động giá (Volatility)","Biến động giá (volatility) là mức độ và tốc độ thay đổi giá của một tài sản trong một khoảng thời gian; biến động càng cao thì giá dao động lên xuống càng mạnh."]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"Chốt lời và cắt lỗ là kế hoạch, không phải bảo hiểm"},"coin":null,"tool":null,"cta":false},"mark-price":{"slug":"mark-price","cat":"derivatives","en":"Mark price","contentLocale":"vi","term":"Giá đánh dấu (Mark price)","aka":["mark price","giá mark","giá hợp lý"],"short":"Giá đánh dấu (mark price) là giá tham chiếu mà sàn dùng để tính lãi lỗ chưa thực hiện và quyết định thanh lý, được xây dựng từ giá chỉ số của nhiều sàn spot.","body":[["Nếu sàn dùng ",["giá giao dịch cuối","last-price"]," để ",["thanh lý","liquidation"],", một lệnh lớn hoặc ",["sổ lệnh","order-book"]," mỏng có thể tạo cú giật giá ngắn và cháy hàng loạt vị thế. Giá đánh dấu giảm rủi ro này vì nó dựa trên ",["giá chỉ số","index-price"],", cộng một phần ",["chênh lệch basis","futures-basis"]," hoặc funding được làm mượt."],"Vì vậy trên màn hình bạn thường thấy ba mức giá: giá giao dịch cuối, giá đánh dấu và giá chỉ số. Trong điều kiện bình thường chúng rất gần nhau; khi thị trường hỗn loạn, chênh lệch có thể lớn hơn.",[["Lệnh cắt lỗ","stop-loss"]," có thể được kích hoạt theo giá giao dịch cuối hoặc giá đánh dấu, tùy bạn chọn khi đặt lệnh. Cách tính giá đánh dấu khác nhau giữa các sàn."]],"example":"Giả sử giá chỉ số ETH là 3.000 USDT. Một lệnh bán thị trường lớn trên hợp đồng perp đẩy giá giao dịch cuối xuống 2.940 USDT trong vài giây, rồi hồi lại. Giá đánh dấu chỉ xuống khoảng 2.995 USDT vì bám theo chỉ số. Một vị thế long có giá thanh lý 2.960 USDT sẽ không bị cháy, dù giá giao dịch cuối đã xuống dưới mức đó.","mistakes":["Theo dõi giá giao dịch cuối để ước tính thanh lý thay vì giá đánh dấu.","Không biết lệnh cắt lỗ của mình dùng loại giá kích hoạt nào.","Nghĩ rằng giá đánh dấu luôn bằng giá spot của một sàn duy nhất."],"faq":[{"q":"Mark price khác last price thế nào?","a":"Last price là giá khớp lệnh gần nhất trên sàn. Mark price là giá tham chiếu làm mượt dựa trên chỉ số, dùng để tính lãi lỗ chưa thực hiện và thanh lý."},{"q":"Vì sao bị thanh lý dù giá chưa chạm giá thanh lý?","a":"Thường là do giá đánh dấu đã chạm mức đó dù giá giao dịch cuối bạn thấy chưa chạm, hoặc do funding và phí làm giá thanh lý dịch lại gần."}],"title":"Mark price (giá đánh dấu) là gì trong futures?","description":"Giá đánh dấu là gì, vì sao sàn dùng mark price để thanh lý thay vì giá giao dịch cuối và cách nó bảo vệ vị thế.","related":[["index-price","Giá chỉ số (Index price)","Giá chỉ số (index price) là giá trung bình có trọng số của một tài sản trên nhiều sàn spot lớn, được dùng làm tham chiếu cho giá đánh dấu và funding rate."],["liquidation-price","Giá thanh lý (Liquidation price)","Giá thanh lý là mức giá đánh dấu mà tại đó vị thế có đòn bẩy của bạn sẽ bị sàn tự động đóng do ký quỹ không còn đủ."],["last-price","Giá giao dịch cuối (Last price)","Giá giao dịch cuối (last price) là mức giá của lệnh khớp gần nhất trên sổ lệnh của một sàn, chính là con số giá bạn thấy thay đổi liên tục trên ứng dụng."],["funding-rate","Funding rate (Tỷ lệ funding)","Funding rate là khoản thanh toán định kỳ giữa phe long và phe short trong hợp đồng tương lai vĩnh cửu, giúp giá hợp đồng bám sát giá spot."]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"Thanh lý: ai đã nhấn nút buộc đóng vị thế?"},"coin":null,"tool":"/funding-rates","cta":false},"instant-convert":{"slug":"instant-convert","cat":"exchange-features","en":"Convert (instant swap)","contentLocale":"vi","term":"Chuyển đổi nhanh (Convert)","aka":["Convert","chuyển đổi","đổi nhanh","instant swap"],"short":"Chuyển đổi nhanh là tính năng cho phép bạn đổi một crypto sang crypto khác với giá báo trước cố định, chỉ bằng một nút bấm, không cần dùng sổ lệnh.","body":[["Trên màn hình Convert, bạn chọn đồng muốn đổi, số lượng và nhận báo giá trong vài giây. Bấm ",["xác nhận","block-confirmations"]," là xong, bạn không phải chọn ",["lệnh giới hạn","limit-order"]," hay ",["lệnh thị trường","market-order"],". Nhiều sàn ghi là không phí, nhưng chi phí thường đã nằm trong chênh lệch giữa giá báo và giá thị trường."],["Convert tiện cho người mới và cho các cặp ít ",["thanh khoản","liquidity"],", vì giá được chốt trước nên bạn không lo ",["trượt giá","slippage"]," trong lúc khớp. Đổi lại, giá báo thường kém hơn một chút so với việc tự đặt lệnh giới hạn trên ",["giao dịch spot","spot-trading"],"."],"Với số tiền lớn hoặc giao dịch thường xuyên, hãy so sánh số coin nhận được qua Convert và qua giao dịch spot với phí maker hoặc taker để chọn cách rẻ hơn."],"example":"Giả sử bạn đổi 1.000 USDT sang SOL. Giá spot đang là 150 USDT, nếu mua spot với phí taker 0,1% bạn nhận khoảng 6,660 SOL. Màn hình Convert báo giá 150,6 USDT và không phí, bạn nhận khoảng 6,640 SOL. Chênh lệch khoảng 0,02 SOL, tương đương 3 USDT. Với khoản nhỏ thì không đáng kể, nhưng nếu bạn đổi 50.000 USDT mỗi tháng, phần chênh lên tới khoảng 150 USDT.","mistakes":["Tin rằng Convert ghi không phí là không tốn chi phí gì.","Dùng Convert cho các giao dịch lớn mà không so sánh với lệnh giới hạn trên spot.","Để báo giá hết hạn rồi bấm xác nhận lại mà không xem giá mới."],"faq":[{"q":"Convert có rẻ hơn giao dịch spot không?","a":"Thường thì không, vì chi phí nằm trong giá báo. Convert đổi lại sự tiện lợi và giá cố định, nhất là với cặp ít thanh khoản."},{"q":"Báo giá Convert có hiệu lực bao lâu?","a":"Thường chỉ vài giây. Khi hết hạn, hệ thống làm mới báo giá theo thị trường và bạn cần xác nhận lại."}],"title":"Convert là gì? Chuyển đổi nhanh crypto trên sàn","description":"Convert cho phép đổi crypto với giá báo trước chỉ bằng một nút bấm. So sánh chi phí ẩn với giao dịch spot và khi nào nên dùng.","related":[["spot-trading","Giao dịch spot (Spot trading)","Giao dịch spot (spot trading) là mua bán tài sản crypto để nhận ngay quyền sở hữu thật ở giá hiện tại, không dùng hợp đồng và mặc định không có đòn bẩy."],["market-order","Lệnh thị trường (Market order)","Lệnh thị trường (market order) là lệnh mua hoặc bán ngay lập tức ở giá tốt nhất hiện có trong sổ lệnh, ưu tiên tốc độ khớp thay vì kiểm soát giá."],["bid-ask-spread","Chênh lệch giá mua-bán (Spread)","Chênh lệch giá mua-bán (bid-ask spread) là khoảng cách giữa giá mua cao nhất (bid) và giá bán thấp nhất (ask) trong sổ lệnh, và là chi phí ngầm mỗi khi bạn mua rồi bán ngay bằng lệnh thị trường."],["slippage","Trượt giá (Slippage)","Trượt giá (slippage) là phần chênh lệch giữa giá bạn dự kiến khi đặt lệnh và giá khớp thực tế, xảy ra khi thanh khoản không đủ hoặc giá thay đổi trong lúc lệnh đang được xử lý."]],"lesson":{"id":"E07","slug":"first-spot-trade","ep":7,"title":"Giao dịch spot đầu tiên: Từ 100 đến 0.002 BTC"},"coin":null,"tool":null,"cta":false},"tokenized-stocks":{"slug":"tokenized-stocks","cat":"tokenized-assets","en":"Tokenized stocks","contentLocale":"vi","term":"Cổ phiếu token hóa (tokenized stocks)","aka":["tokenized stocks","cổ phiếu token hóa","cổ phiếu on-chain","xStocks"],"short":"Cổ phiếu token hóa là token đại diện cho giá trị của một cổ phiếu niêm yết như Apple hay Tesla, thường được bảo chứng bởi cổ phiếu thật do một đơn vị lưu ký nắm giữ.","body":[["Nhà phát hành mua cổ phiếu thật, giữ tại đơn vị lưu ký, rồi phát hành token tương ứng trên ",["blockchain","blockchain"],". Token có thể giao dịch trên ",["sàn tập trung","centralized-exchange"]," hoặc ",["DEX","dex"],", đôi khi gần như 24/7, và có thể mua lẻ một phần nhỏ của cổ phiếu."],"Người nắm giữ token thường không trực tiếp sở hữu cổ phiếu, không có quyền biểu quyết, và quyền nhận cổ tức tùy cấu trúc sản phẩm. Bạn chịu thêm rủi ro của nhà phát hành và đơn vị lưu ký, ngoài rủi ro giá cổ phiếu.","Khi sàn chứng khoán gốc đóng cửa vào cuối tuần hoặc ngày lễ, token vẫn có thể giao dịch nhưng giá có thể lệch so với giá đóng cửa. Khả năng mua cổ phiếu token hóa cũng bị giới hạn theo khu vực, và nhiều sản phẩm không phục vụ người dùng tại Mỹ."],"example":["Giả sử cổ phiếu XYZ đóng cửa thứ Sáu ở 200 USD. Token XYZ được bảo chứng 1:1 vẫn giao dịch cuối tuần. Một tin tốt xuất hiện thứ Bảy và token tăng lên 206 USD, cao hơn 3%. Bạn mua 0,5 token với 103 ",["USDT","usdt"],". Thứ Hai, cổ phiếu chỉ mở cửa ở 202 USD và token quay về sát mức đó, khoảng 101 USDT cho 0,5 token. Bạn lỗ khoảng 2 USDT vì đã mua lúc giá lệch."],"mistakes":["Nghĩ mua token cổ phiếu là có quyền cổ đông như mua qua công ty chứng khoán.","Bỏ qua rủi ro nhà phát hành và đơn vị lưu ký.","Mua cuối tuần khi giá token lệch xa giá đóng cửa của cổ phiếu gốc."],"faq":[{"q":"Cổ phiếu token hóa có nhận cổ tức không?","a":"Tùy sản phẩm. Một số tự động cộng thêm token hoặc trả tiền tương ứng cổ tức, một số thì không. Hãy đọc tài liệu của nhà phát hành."},{"q":"Cổ phiếu token hóa khác hợp đồng vĩnh cửu cổ phiếu thế nào?","a":"Token cổ phiếu thường được bảo chứng bằng cổ phiếu thật và không có đòn bẩy. Hợp đồng vĩnh cửu cổ phiếu chỉ theo dõi giá, có đòn bẩy, funding rate và rủi ro thanh lý."}],"title":"Cổ phiếu token hóa là gì? Mua cổ phiếu Mỹ bằng crypto","description":"Cổ phiếu token hóa là token đại diện cho cổ phiếu thật. Tìm hiểu cách bảo chứng, quyền lợi, giao dịch cuối tuần và các rủi ro.","related":[["stock-perpetuals","Hợp đồng vĩnh cửu cổ phiếu (stock perpetuals)","Hợp đồng vĩnh cửu cổ phiếu là hợp đồng tương lai không có ngày đáo hạn, theo dõi giá một cổ phiếu hoặc chỉ số chứng khoán và được giao dịch bằng ký quỹ crypto như USDT."],["real-world-assets","Tài sản thực (RWA)","Tài sản thực, hay RWA, là các tài sản ngoài blockchain như trái phiếu, vàng, bất động sản hay khoản vay được token hóa để có thể nắm giữ và giao dịch trên chuỗi."],["spot-bitcoin-etf","ETF Bitcoin giao ngay (spot Bitcoin ETF)","ETF Bitcoin giao ngay là quỹ hoán đổi danh mục niêm yết trên sàn chứng khoán, nắm giữ BTC thật và cho nhà đầu tư tiếp xúc với giá Bitcoin qua tài khoản chứng khoán."],["usdc","USDC (USD Coin)","USDC là stablecoin do công ty Circle phát hành, neo 1:1 với đô la Mỹ và được đảm bảo bằng tiền mặt cùng tài sản ngắn hạn tương đương tiền."]],"lesson":null,"coin":null,"tool":"/topics/tokenized-stocks-vs-perpetuals","cta":true}});
